<?php require_once __DIR__.'/../includes/functions.php';$row=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$ref=trim((string)post('reference_no'));$pid=trim((string)post('patient_id'));if($ref||$pid){$sql='SELECT a.reference_no,a.appointment_date,a.appointment_time,a.status,s.name service_name,r.patient_id FROM appointments a JOIN services s ON s.id=a.service_id LEFT JOIN residents r ON r.id=a.resident_id WHERE ';$params=[];if($ref){$sql.='a.reference_no=?';$params[]=$ref;}else{$sql.='r.patient_id=?';$params[]=$pid;}$sql.=' ORDER BY a.appointment_date DESC LIMIT 1';$q=db()->prepare($sql);$q->execute($params);$row=$q->fetch();}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Check Appointment | CHMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=BASE_URL?>/assets/css/public.css" rel="stylesheet"></head><body><?php include __DIR__.'/../includes/public_nav.php';?><main class="container py-5"><div class="public-card mx-auto" style="max-width:700px"><h1>Check Appointment</h1><p class="text-muted">Enter an appointment reference number or Patient ID. Only minimal appointment information is shown.</p><form method="post" class="row g-3"><?=csrf_field()?><div class="col-md-6"><label>Appointment Reference</label><input name="reference_no" class="form-control"></div><div class="col-md-6"><label>Patient ID</label><input name="patient_id" class="form-control"></div><div class="col-12"><button class="btn btn-primary">Check Status</button></div></form><?php if($_SERVER['REQUEST_METHOD']==='POST'):if($row):?><hr><h4>Status: <span class="badge text-bg-secondary"><?=e($row['status'])?></span></h4><p class="mb-0"><b>Patient ID:</b> <?=e($row['patient_id'])?><br><b>Reference:</b> <?=e($row['reference_no'])?><br><b>Date:</b> <?=e($row['appointment_date'])?><br><b>Time:</b> <?=e($row['appointment_time'])?><br><b>Service:</b> <?=e($row['service_name'])?></p><?php else:?><hr><div class="alert alert-warning">No matching appointment was found.</div><?php endif;endif;?></div></main></body></html>
